#![allow(clippy::excessive_precision)]

use thermopack_rs::Cubic;
use thermopack_rs::CubicKind;

const RTOL: f64 = 1e-6;
const ATOL: f64 = 1e-9;

fn close(source: f64, native: f64) -> bool {
    if source.is_nan() || native.is_nan() {
        return source.is_nan() && native.is_nan();
    }
    (source - native).abs() <= ATOL + RTOL * source.abs()
}

#[test]
fn isolines_match_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/isolines.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let line = parts[0];
        let kind = match parts[1] {
            "SRK" => CubicKind::SoaveRedlichKwong,
            "RK" => CubicKind::RedlichKwong,
            "VDW" => CubicKind::VanDerWaals,
            _ => CubicKind::PengRobinson,
        };
        let components: Vec<&str> = parts[2].split(',').collect();
        let composition: Vec<f64> = parts[3].split(',').map(|v| v.parse().unwrap()).collect();
        let value: f64 = parts[4].parse().unwrap();
        let minimum: f64 = parts[5].parse().unwrap();
        let maximum: f64 = parts[6].parse().unwrap();
        let lower = if parts[7] == "none" {
            None
        } else {
            Some(parts[7].parse::<f64>().unwrap())
        };
        let upper = if parts[8] == "none" {
            None
        } else {
            Some(parts[8].parse::<f64>().unwrap())
        };
        let points: usize = parts[9].parse().unwrap();
        let model = Cubic::new(kind, &components).unwrap();
        let line_result = match line {
            "isobar" => thermopack_rs::isolines::isobar(
                &model,
                value,
                minimum,
                maximum,
                &composition,
                points,
            )
            .unwrap(),
            "isenthalp" => thermopack_rs::isolines::isenthalp(
                &model,
                thermopack_rs::isolines::CaloricLine {
                    specification: value,
                    minimum_pressure: minimum,
                    maximum_pressure: maximum,
                    minimum_temperature: lower.unwrap(),
                    maximum_temperature: upper.unwrap(),
                },
                &composition,
                points,
            )
            .unwrap(),
            "isentrope" => thermopack_rs::isolines::isentrope(
                &model,
                thermopack_rs::isolines::CaloricLine {
                    specification: value,
                    minimum_pressure: minimum,
                    maximum_pressure: maximum,
                    minimum_temperature: lower.unwrap(),
                    maximum_temperature: upper.unwrap(),
                },
                &composition,
                points,
            )
            .unwrap(),
            _ => thermopack_rs::isolines::isotherm(
                &model,
                value,
                minimum,
                maximum,
                &composition,
                points,
            )
            .unwrap(),
        };
        let source_temperature: f64 = fields[2].parse().unwrap();
        let source_pressure: f64 = fields[3].parse().unwrap();
        let source_volume: f64 = fields[4].parse().unwrap();
        let source_entropy: f64 = fields[5].parse().unwrap();
        let source_enthalpy: f64 = fields[6].parse().unwrap();
        let index: usize = fields[1].parse().unwrap();
        assert!(
            close(source_temperature, line_result.temperature[index]),
            "{case} {index}"
        );
        assert!(
            close(source_pressure, line_result.pressure[index]),
            "{case} {index}"
        );
        assert!(
            close(source_volume, line_result.volume[index]),
            "{case} {index}"
        );
        assert!(
            close(source_entropy, line_result.entropy[index]),
            "{case} {index}"
        );
        assert!(
            close(source_enthalpy, line_result.enthalpy[index]),
            "{case} {index}"
        );
        checked += 1;
    }
    assert!(checked > 80);
}

#[test]
fn the_isotherm_splits_at_the_saturation_pressure() {
    // The isotherm of a pure fluid below its critical temperature runs
    // through the two phase region, so the grid carries the saturation
    // pressure and the liquid branch follows the vapor branch.
    let model = Cubic::new(CubicKind::PengRobinson, &["C1"]).unwrap();
    let line = thermopack_rs::isolines::isotherm(&model, 150.0, 1.0e5, 1.0e7, &[1.0], 10).unwrap();
    let saturation = model.pseudo_saturation_pressure(150.0, &[1.0]).unwrap();
    assert!(saturation.pressure > 1.0e5 && saturation.pressure < 1.0e7);
    // The grid of ten points splits into the vapor branch and the liquid
    // branch, and the saturation pressure is the end of the first one.
    let mut first_liquid = None;
    for index in 0..line.pressure.len() {
        if line.pressure[index] > saturation.pressure {
            first_liquid = Some(index);
            break;
        }
    }
    let first_liquid = first_liquid.expect("liquid branch");
    assert!(first_liquid > 0);
    assert!((line.pressure[first_liquid - 1] - saturation.pressure).abs() < 1.0e-6);
    // The liquid branch compresses with the pressure.
    let last = line.pressure.len() - 1;
    assert!(line.volume[last] < line.volume[first_liquid]);
}

#[test]
fn the_isobar_splits_at_the_saturation_temperature() {
    let model = Cubic::new(CubicKind::PengRobinson, &["C1"]).unwrap();
    let line = thermopack_rs::isolines::isobar(&model, 1.0e6, 120.0, 190.0, &[1.0], 8).unwrap();
    let saturation = model.pseudo_saturation_temperature(1.0e6, &[1.0]).unwrap();
    assert!(saturation.temperature > 120.0 && saturation.temperature < 190.0);
    let mut first_vapor = None;
    for index in 0..line.temperature.len() {
        if line.temperature[index] > saturation.temperature {
            first_vapor = Some(index);
            break;
        }
    }
    let first_vapor = first_vapor.expect("vapor branch");
    assert!(first_vapor > 0);
    assert!((line.temperature[first_vapor - 1] - saturation.temperature).abs() < 1.0e-9);
    assert!(line.volume[first_vapor] > line.volume[0]);
}

#[test]
fn the_isenthalp_holds_the_enthalpy() {
    let model = Cubic::new(CubicKind::PengRobinson, &["C1"]).unwrap();
    let line = thermopack_rs::isolines::isenthalp(
        &model,
        thermopack_rs::isolines::CaloricLine {
            specification: -78000.0,
            minimum_pressure: 1.0e5,
            maximum_pressure: 1.0e7,
            minimum_temperature: 150.0,
            maximum_temperature: 250.0,
        },
        &[1.0],
        8,
    )
    .unwrap();
    assert!(!line.pressure.is_empty());
    for index in 0..line.pressure.len() {
        assert!((line.enthalpy[index] + 78000.0).abs() < 1.0e-6);
    }
}

#[test]
fn the_isentrope_holds_the_entropy() {
    let model = Cubic::new(CubicKind::PengRobinson, &["C1"]).unwrap();
    let line = thermopack_rs::isolines::isentrope(
        &model,
        thermopack_rs::isolines::CaloricLine {
            specification: 165.0,
            minimum_pressure: 1.0e5,
            maximum_pressure: 5.0e5,
            minimum_temperature: 150.0,
            maximum_temperature: 250.0,
        },
        &[1.0],
        8,
    )
    .unwrap();
    assert!(!line.pressure.is_empty());
    for index in 0..line.pressure.len() {
        assert!((line.entropy[index] - 165.0).abs() < 1.0e-6);
    }
}
